import React, { useEffect, useState } from 'react';
import TeamsTable from './TeamsTable';
import TeamPage from './TeamPage';
import KeeperComparison from './KeeperComparison';
import DataPreview from './DataPreview';
import { loadPreviewData } from './previewData';
import { SeasonAwards, PayoutRace, PlayoffPicture } from './LeagueInsightPanels';
import WeeklyMatchups from './WeeklyMatchups';
import { features } from './features';
import { formatMoney, normalizeData, teamHref } from './dashboardData';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

function useRoute() {
  const [route, setRoute] = useState(() => window.location.hash.slice(1) || '/');
  useEffect(() => {
    const update = () => { setRoute(window.location.hash.slice(1) || '/'); window.scrollTo(0, 0); };
    window.addEventListener('hashchange', update);
    return () => window.removeEventListener('hashchange', update);
  }, []);
  return route;
}

export default function FantasyDashboard() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [attempt, setAttempt] = useState(0);
  const [previewId, setPreviewId] = useState(process.env.NODE_ENV === 'development' ? '2025w12' : 'current');
  const route = useRoute();
  useEffect(() => { document.documentElement.setAttribute('data-bs-theme', 'dark'); }, []);
  useEffect(() => {
    const controller = new AbortController();
    setError(null);
    const request = previewId === 'current' ? fetch(`${process.env.PUBLIC_URL}/league_data.json`, { signal: controller.signal })
      .then((response) => {
        if (!response.ok) throw new Error(`Could not load league data (HTTP ${response.status}).`);
        return response.json();
      }) : loadPreviewData(previewId);
    request.then((json) => { if (!controller.signal.aborted) setData(normalizeData(json)); })
      .catch((err) => { if (!controller.signal.aborted) setError(err.message); });
    return () => controller.abort();
  }, [attempt, previewId]);
  const team = data?.teams.find((entry) => teamHref(entry).slice(1) === route);
  const weekly = features.weeklyResults && /^\/weeks\/\d+$/.test(route);
  const week = weekly ? Number(route.split('/')[2]) : null;
  const overview = route === '/';
  const keeperBoard = route === '/keepers';
  const validWeek = weekly && week >= 1 && week <= data?.weeks;
  useEffect(() => {
    document.title = `${keeperBoard ? 'Keeper comparison · ' : team ? `${team.name} · ` : ''}FuToN League Dashboard`;
  }, [team, keeperBoard]);
  return (
    <div className="dashboard-shell">
      <header className="site-header"><a className="brand" href="#/"><img className="brand-mark" src={`${process.env.PUBLIC_URL}/logo192.png`} alt="" /><span>FuToN<span className="brand-subtitle">League dashboard</span></span></a>
        {data && <div className="team-navigation"><a className={overview ? 'nav-overview active' : 'nav-overview'} href="#/" aria-current={overview ? 'page' : undefined}>League overview</a><a className={keeperBoard ? 'nav-overview active' : 'nav-overview'} href="#/keepers" aria-current={keeperBoard ? 'page' : undefined}>Keeper board</a><label className="visually-hidden" htmlFor="team-navigation">View a team</label><select id="team-navigation" value={team?.team_id ?? ''} onChange={(event) => { window.location.hash = event.target.value ? teamHref({ team_id: event.target.value }) : '#/'; }}><option value="">Choose a team</option>{[...data.teams].sort((a, b) => a.name.localeCompare(b.name)).map((entry) => <option key={entry.team_id} value={entry.team_id}>{entry.name}</option>)}</select></div>}
      </header>
      <main id="main-content">
        {process.env.NODE_ENV === 'development' && <DataPreview value={previewId} onChange={(id) => {
          setData(null);
          setPreviewId(id);
          window.location.hash = '#/';
        }} />}
        {error ? <section className="panel" role="alert"><h1>League data couldn’t load</h1><p>{error}</p><button className="retry-button" onClick={() => setAttempt(attempt + 1)}>Try again</button></section> : !data ? <p role="status" className="empty-state">Loading league dashboard…</p> : <>
          <div className="data-status"><span>{data.metadata?.season ? `${data.metadata.season} season · ` : ''}Through Week {data.metadata?.latest_completed_week ?? data.weeks}</span>{data.metadata?.generated_at && <span>Updated {new Date(data.metadata.generated_at).toLocaleString()}</span>}</div>
          {overview ? <>
            <section className="page-heading"><p className="eyebrow">Your league, at a glance</p><h1>League overview</h1><p className="muted">Follow the standings. Open a team for keeper eligibility, payouts, and season details.</p></section>
            <section className="panel standings-panel" aria-labelledby="standings-title"><div className="section-heading"><div><p className="eyebrow">Regular season</p><h2 id="standings-title">Standings</h2></div><span className="count-badge">{data.teams.length} teams</span></div><TeamsTable teams={data.teams} metadata={data.metadata} /><p className="muted table-note">ROLLING is the all-play record: every team plays every other team each week. Playoff GB measures the gap to the last playoff spot. M# is the magic number to clinch, reduced by your wins and relevant rivals’ losses. E# counts combined own losses and cutoff-team wins toward elimination. Clinched and Out mark settled spots. Ties count as half a win. Points-for tiebreaks and the remaining schedule can affect elimination.</p></section>
            <section className="panel" aria-labelledby="league-payouts"><div className="section-heading"><div><p className="eyebrow">League awards</p><h2 id="league-payouts">Payouts earned</h2></div><strong className="payout-total">{formatMoney(data.teams.reduce((total, entry) => total + (entry.payout ?? 0), 0))}</strong></div><p className="muted">Open a team to see its payout breakdown.</p><ul className="payout-grid">{[...data.teams].sort((a, b) => b.payout - a.payout || a.name.localeCompare(b.name)).map((entry) => <li key={entry.team_id}><a href={teamHref(entry)}>{entry.name}</a><strong>{formatMoney(entry.payout)}</strong></li>)}</ul></section>
            <PayoutRace teams={data.teams} />
            <PlayoffPicture data={data} />
            <SeasonAwards data={data} />
            {features.weeklyResults && <section className="panel"><h2>Weekly results</h2><nav aria-label="Weeks" className="week-links">{Array.from({ length: data.weeks }, (_, index) => <a key={index} href={`#/weeks/${index + 1}`}>Week {index + 1}</a>)}</nav></section>}
          </> : keeperBoard ? <KeeperComparison data={data} /> : team ? <TeamPage team={team} data={data} /> : validWeek ? <WeeklyMatchups key={week} week={week} matchups={data.matchups} ranks={data.ranks} /> : <section className="panel"><h1>Page not found</h1><p>This team or page isn’t available for this season.</p><a href="#/">Return to league overview</a></section>}
        </>}
      </main>
      <footer className="site-footer">FuToN Fantasy Football</footer>
    </div>
  );
}
