export const formatPoints = (value) => Number(value ?? 0).toLocaleString('en-US', {
  minimumFractionDigits: 2, maximumFractionDigits: 2,
});
export const formatMoney = (value) => Number(value ?? 0).toLocaleString('en-US', {
  style: 'currency', currency: 'USD', maximumFractionDigits: 0,
});
export const record = (team, prefix = '') => `${team[`${prefix}wins`] ?? 0}–${team[`${prefix}losses`] ?? 0}${team[`${prefix}ties`] ? `–${team[`${prefix}ties`]}` : ''}`;
export const rollingPercentage = (team) => {
  const games = team.rolling_wins + team.rolling_losses + team.rolling_ties;
  return games ? (team.rolling_wins + team.rolling_ties / 2) / games : 0;
};
export const teamHref = (team) => `#/teams/${encodeURIComponent(team.team_id)}`;

export function playerProduction(team, matchups) {
  const players = new Map();
  for (const matchup of matchups) {
    if (matchup.matchup_type && matchup.matchup_type !== 'regular') continue;
    for (const side of ['team0', 'team1']) {
      const weeklyTeam = matchup[side];
      if (!weeklyTeam) continue;
      const matches = weeklyTeam.team_id != null && team.team_id != null
        ? String(weeklyTeam.team_id) === String(team.team_id) : weeklyTeam.name === team.name;
      if (!matches) continue;
      for (const player of weeklyTeam.roster ?? []) {
        if (!player.selected_position || ['BN', 'IR'].includes(player.selected_position)) continue;
        const key = player.yahoo_player_key ?? player.name;
        const previous = players.get(key);
        players.set(key, {
          ...player, key,
          starts: (previous?.starts ?? 0) + 1,
          pointHundredths: (previous?.pointHundredths ?? 0) + Math.round(Number(player.points ?? 0) * 100),
        });
      }
    }
  }
  return [...players.values()]
    .map((player) => ({ ...player, points: player.pointHundredths / 100 }))
    .sort((a, b) => b.points - a.points || a.name.localeCompare(b.name));
}

export function normalizeData(data) {
  if (!data || !data.teams || !Array.isArray(data.matchups)) {
    throw new Error('The league data file is missing teams or matchups.');
  }
  const teams = Object.entries(data.teams).map(([name, team]) => ({
    ...team, name, team_id: String(team.team_id ?? name),
    rolling_ties: team.rolling_ties ?? 0,
    eligible_keepers: (data.eligible_keepers ?? []).find((entry) =>
      team.team_id != null && entry.team_id != null
        ? String(entry.team_id) === String(team.team_id) : entry.name === name
    )?.eligible_keepers ?? [],
  }));
  const ranked = [...teams].sort((a, b) => rollingPercentage(b) - rollingPercentage(a));
  let previousPercentage;
  let rank;
  ranked.forEach((team, index) => {
    const percentage = rollingPercentage(team);
    if (percentage !== previousPercentage) rank = index + 1;
    team.rolling_rank = rank;
    previousPercentage = percentage;
  });
  return { ...data, teams };
}
