import React, { useState } from 'react';
import { formatPoints } from './dashboardData';
import { positionProduction, scheduleLuck } from './leagueInsights';

export function PositionProduction({ team, matchups }) {
  const positions = positionProduction(team, matchups);
  const total = positions.reduce((sum, position) => sum + position.points, 0);
  const negative = positions.reduce((sum, position) => sum + Math.min(0, position.points), 0);
  const positive = positions.reduce((sum, position) => sum + Math.max(0, position.points), 0);
  const [selected, setSelected] = useState(null);
  const active = positions.find((position) => position.label === selected);
  let offset = 0;
  const segments = positions.filter((position) => position.points > 0).map((position) => {
    const share = position.points / positive * 100;
    const segment = { ...position, share, offset };
    offset += share;
    return segment;
  });
  return <section className="panel" aria-labelledby="position-title">
    <div className="section-heading"><div><p className="eyebrow">Where the points come from</p><h2 id="position-title">Production by position</h2></div></div>
    <p className="muted small-note insights-description">Regular-season starter points by football position. FLEX uses the player’s position.</p>
    {positions.length ? <>
      <div className="position-breakdown">
        <svg className="position-donut" viewBox="0 0 220 220" role="img" aria-label={`Position contributions totaling ${formatPoints(total)} points. ${positions.map((p) => `${p.label}: ${formatPoints(p.points)}`).join('; ')}${negative < 0 ? '. Donut slices show positive totals; negative totals appear in the legend.' : ''}`}>
          <circle className="donut-track" cx="110" cy="110" r="84" />
          {segments.map((position) => <circle key={position.label} cx="110" cy="110" r="84" pathLength="100"
            className="donut-segment" stroke={position.color} strokeDasharray={`${position.share} ${100 - position.share}`}
            strokeDashoffset={-position.offset} transform="rotate(-90 110 110)"
            style={{ opacity: active && active.label !== position.label ? 0.25 : 1 }}>
            <title>{position.label}: {formatPoints(position.points)} points ({position.share.toFixed(1)}%{negative < 0 ? ' of positive totals' : ''})</title>
          </circle>)}
          <text className="donut-value" x="110" y="109">{formatPoints(active?.points ?? total)}</text>
          <text className="donut-label" x="110" y="132">{active ? `${active.label} points` : 'Net starter points'}</text>
        </svg>
        <ul className="position-totals">{positions.map((position) => <li key={position.label}>
          <button className="position-detail" style={{ '--position-color': position.color }} aria-pressed={selected === position.label} onClick={() => setSelected(selected === position.label ? null : position.label)}>
            <span className="position-label"><i aria-hidden="true" />{position.label}</span>
            <strong>{formatPoints(position.points)}</strong>
            <span className="muted">{total > 0 ? `${(position.points / total * 100).toFixed(1)}% of net points` : 'points'}</span>
          </button>
        </li>)}</ul>
      </div>
      {negative < 0 && <p className="muted small-note">Donut slices show positive position totals. Negative totals are included in the net points and listed alongside the chart.</p>}
    </> : <p className="empty-state">No regular-season starts yet.</p>}
  </section>;
}

export function LuckComparison({ team }) {
  const luck = scheduleLuck(team);
  const signed = (number, digits = 1) => `${number > 0 ? '+' : ''}${number.toFixed(digits)}`;
  return <section className="panel" aria-labelledby="luck-title">
    <div className="section-heading"><div><p className="eyebrow">A little schedule perspective</p><h2 id="luck-title">How lucky am I?</h2></div></div>
    {luck ? <>
      <div className="luck-summary"><strong className={luck.gap < 0 ? 'luck-below' : 'luck-above'}>{signed(luck.extraWins)} wins</strong><span className="muted">{Math.abs(luck.gap) < 0.00001 ? 'Right on all-play pace' : luck.gap > 0 ? 'Above all-play pace' : 'Below all-play pace'}</span></div>
      <div className="luck-bars">{[['Actual win rate', luck.actual, 'actual'], ['All-play win rate', luck.allPlay, 'all-play']].map(([label, value, key]) => <div className="luck-row" key={key}>
        <span>{label}</span><div className={`luck-track luck-${key}`} aria-hidden="true"><span style={{ width: `${value * 100}%` }} /></div><strong>{(value * 100).toFixed(1)}%</strong>
      </div>)}</div>
      <p className="muted small-note">Your actual win rate is {signed(luck.gap * 100)} percentage points relative to your all-play rate. At your all-play rate, {luck.games} games would be worth {(luck.allPlay * luck.games).toFixed(1)} wins. Ties count as half a win. The gap is a rough indicator of schedule luck.</p>
    </> : <p className="empty-state">Play a regular-season game to compare actual and all-play results.</p>}
  </section>;
}
