import React from 'react';
import PlayerProduction from './PlayerProduction';
import DraftPicks from './DraftPicks';
import TeamResults from './TeamResults';
import { PositionProduction, LuckComparison } from './TeamInsights';
import { formatMoney, formatPoints, record, rollingPercentage } from './dashboardData';

export function KeeperStatus({ metadata }) {
  if (!metadata?.keeper_roster_week) return null;
  return <p className="muted">{metadata.keepers_final ? 'Eligibility based on' : 'Provisional eligibility through'} Week {metadata.keeper_roster_week}.
    {!metadata.keepers_final && ` Keeper rosters lock in Week ${metadata.keeper_lock_week}.`}</p>;
}

function KeeperList({ keepers }) {
  return keepers.length ? (
    <div className="keeper-grid">{[...keepers].sort((a, b) => a.round - b.round || a.player.name.localeCompare(b.player.name)).map((keeper) => (
      <article className="keeper-card" key={keeper.player.yahoo_player_key ?? keeper.player.name}>
        <div className="keeper-player"><img src={keeper.player.headshot_image} alt="" loading="lazy" />
          <div><h3>{keeper.player.name}</h3><p className="muted">{keeper.player.team} · {keeper.player.positions.join(', ')}</p></div>
        </div>
        <div className="keeper-cost"><span>Eligible round <strong>{keeper.round}</strong></span><span className={`tier-badge tier-${keeper.tier}`}>{keeper.tier}</span></div>
        <p className="draft-history">{keeper.draft_status}</p>
      </article>
    ))}</div>
  ) : <p className="empty-state">No eligible keepers.</p>;
}

export default function TeamPage({ team, data }) {
  const pointsLeft = team.optimal_points_for - team.points_for;
  const efficiency = team.optimal_points_for ? team.points_for / team.optimal_points_for * 100 : null;
  return (
    <>
      <a className="back-link" href="#/">← League overview</a>
      <section className="team-heading"><img src={team.logo_image} alt="" /><div><p className="eyebrow">Team clubhouse</p><h1>{team.name}</h1><p className="muted">{data.metadata?.season ?? 'Season'} · Regular-season record {record(team)}</p></div></section>
      <section className="panel" aria-labelledby="keepers-title">
        <div className="section-heading"><div><p className="eyebrow">Plan for next season</p><h2 id="keepers-title">Eligible keepers</h2></div><span className="count-badge">{team.eligible_keepers.length} eligible</span></div>
        <KeeperStatus metadata={data.metadata} />
        <KeeperList keepers={team.eligible_keepers} />
      </section>
      <DraftPicks team={team} />
      <section className="panel" aria-labelledby="season-summary-title">
        <div className="section-heading"><div><p className="eyebrow">The season so far</p><h2 id="season-summary-title">Season summary</h2></div></div>
        <dl className="stat-grid">
          <div><dt>Actual record</dt><dd>{record(team)}</dd></div>
          <div><dt>Points for</dt><dd>{formatPoints(team.points_for)}</dd></div>
          <div><dt>Points against</dt><dd>{formatPoints(team.points_against)}</dd></div>
          <div><dt>ROLLING rank</dt><dd>#{team.rolling_rank}</dd></div>
          <div><dt>ROLLING record</dt><dd>{record(team, 'rolling_')}</dd></div>
          <div><dt>All-play win rate</dt><dd>{(rollingPercentage(team) * 100).toFixed(1)}%</dd></div>
        </dl>
        <p className="muted small-note">ROLLING compares your score with every other team each regular-season week. Ties count as half a win in the win rate.</p>
        <details className="lineup-details">
          <summary>Lineup performance <span className="muted">Optimal results and points left on the bench</span></summary>
          <p className="muted">Regular-season results if every team had started its highest-scoring eligible lineup each week.</p>
          <dl className="stat-grid">
            <div><dt>Optimal record</dt><dd>{record(team, 'optimal_')}</dd></div>
            <div><dt>Optimal points for</dt><dd>{formatPoints(team.optimal_points_for)}</dd></div>
            <div><dt>Optimal points against</dt><dd>{formatPoints(team.optimal_points_against)}</dd></div>
            <div><dt>Points left on bench</dt><dd>{formatPoints(pointsLeft)}</dd></div>
            <div><dt>Lineup efficiency</dt><dd>{efficiency == null ? '—' : `${efficiency.toFixed(1)}%`}</dd></div>
          </dl>
        </details>
      </section>
      <TeamResults team={team} data={data} />
      <LuckComparison team={team} />
      <PositionProduction team={team} matchups={data.matchups} />
      <PlayerProduction team={team} matchups={data.matchups} />
      <section className="panel" aria-labelledby="payout-title">
        <div className="section-heading"><div><p className="eyebrow">League awards</p><h2 id="payout-title">Payout earned</h2></div><strong className="payout-total">{formatMoney(team.payout)}</strong></div>
        {team.payout_items?.length ? <ul className="award-list">{team.payout_items.map((item, index) => <li key={index}><span>{item.label}</span><strong>{formatMoney(item.amount)}</strong></li>)}</ul> : <p className="muted">{team.payout ? 'Award breakdown unavailable.' : 'No payouts earned yet.'}</p>}
        {team.playoff_result && <p className="muted">Playoff finish: {team.playoff_result}</p>}
      </section>

    </>
  );
}
