import React, { useState } from 'react';
import { formatPoints, record, teamHref } from './dashboardData';
import { playoffStandings } from './leagueInsights';

const columns = [
  ['name', 'Team'], ['wins', 'Record'], ['points_for', 'Points For'],
  ['points_against', 'Points Against'], ['playoff_games_back', 'Playoff GB'],
  ['playoff_number', 'M# / E#'],
  ['rolling_wins', 'ROLLING Record'],
];

export default function TeamsTable({ teams, metadata }) {
  const [sort, setSort] = useState({ key: 'wins', ascending: false });
  const sorted = playoffStandings(teams, metadata).sort((a, b) => {
    if (sort.key === 'playoff_number') {
      const order = { clinched: 0, magic: 1, tiebreak: 2, elimination: 3, out: 4 };
      const result = order[a.playoff_status] - order[b.playoff_status]
        || (a.playoff_number ?? 0) - (b.playoff_number ?? 0);
      return (sort.ascending ? result : -result) || a.name.localeCompare(b.name);
    }
    // Missing values sort after populated values.
    if (a[sort.key] == null && b[sort.key] != null) return 1;
    if (b[sort.key] == null && a[sort.key] != null) return -1;
    let result = typeof a[sort.key] === 'string'
      ? a[sort.key].localeCompare(b[sort.key]) : a[sort.key] - b[sort.key];
    if (!result && ['wins', 'rolling_wins'].includes(sort.key)) {
      const prefix = sort.key === 'wins' ? '' : 'rolling_';
      result = (a[`${prefix}ties`] ?? 0) - (b[`${prefix}ties`] ?? 0) || a.points_for - b.points_for;
    }
    return (sort.ascending ? result : -result) || a.name.localeCompare(b.name);
  });
  const requestSort = (key) => setSort((current) => ({
    key, ascending: current.key === key ? !current.ascending : ['name', 'playoff_games_back', 'playoff_number'].includes(key),
  }));
  return (
    <div className="table-scroll" tabIndex="0" role="region" aria-label="Scrollable league standings">
      <table className="standings-table">
        <caption className="visually-hidden">Regular-season standings. Select a team to view keepers and season details.</caption>
        <thead><tr>{columns.map(([key, label]) => (
          <th key={key} scope="col" aria-sort={sort.key === key ? (sort.ascending ? 'ascending' : 'descending') : 'none'}>
            <button onClick={() => requestSort(key)} title={key === 'playoff_games_back' ? 'Games behind the final playoff spot' : key === 'playoff_number' ? 'M: magic number to clinch; E: elimination number. Sort by status and number' : undefined}>{label} <span aria-hidden="true">{sort.key === key ? (sort.ascending ? '↑' : '↓') : '↕'}</span></button>
          </th>
        ))}</tr></thead>
        <tbody>{sorted.map((team) => (
          <tr key={team.team_id}>
            <th scope="row"><a className="team-link" href={teamHref(team)}><img src={team.logo_image} alt="" loading="lazy" />{team.name}</a></th>
            <td className="record-value">{record(team)}</td>
            <td>{formatPoints(team.points_for)}</td>
            <td>{formatPoints(team.points_against)}</td>
            <td title={team.playoff_in_position ? 'Currently in playoff position' : 'Games behind the final playoff spot'}>{team.playoff_in_position ? '—' : team.playoff_games_back}</td>
            <td><PlayoffNumber team={team} /></td>
            <td>{record(team, 'rolling_')}</td>
          </tr>
        ))}</tbody>
      </table>
    </div>
  );
}


function PlayoffNumber({ team }) {
  const displays = {
    magic: { text: `M${team.magic_number}`, color: 'magic-number', title: `Magic number ${team.magic_number}: own wins needed to guarantee a playoff spot, reduced by relevant rivals’ losses` },
    elimination: { text: `E${team.elimination_number}`, color: 'elimination-number', title: `Elimination number ${team.elimination_number}: combined own losses and cutoff-team wins` },
    clinched: { text: 'Clinched', color: 'magic-number', title: 'Playoff place secured' },
    out: { text: 'Out', color: 'elimination-number', title: 'Eliminated from playoff contention' },
    tiebreak: { text: 'Tiebreak', color: 'playoff-tiebreak', title: 'Final playoff place depends on an unresolved tiebreak' },
  };
  const display = displays[team.playoff_status];
  return <span className={`playoff-number ${display.color}`} title={display.title}>{display.text}</span>;
}
