import React, { useMemo } from 'react';
import { formatPoints, playerProduction } from './dashboardData';

import { positionStyles, positionFor } from './positionStyles';

export default function PlayerProduction({ team, matchups }) {
  const players = useMemo(() => playerProduction(team, matchups), [team, matchups]);
  const total = players.reduce((sum, player) => sum + player.pointHundredths, 0) / 100;
  const minimum = Math.min(0, ...players.map((player) => player.points));
  const maximum = Math.max(0, ...players.map((player) => player.points));
  const range = maximum - minimum || 1;
  const zero = -minimum / range * 100;
  const legend = [...new Set(players.map((player) => positionFor(player).label))];

  return (
    <section className="panel production-panel" aria-labelledby="production-title">
      <div className="section-heading">
        <div><p className="eyebrow">Who put points on the board</p><h2 id="production-title">Player production</h2></div>
        <span className="count-badge">{players.length} contributors</span>
      </div>
      <p className="muted small-note production-description">
        Points scored in your starting lineup during the regular season, including players you’ve since traded or dropped. Bench and IR points are excluded.
      </p>
      {players.length ? <>
        <ul className="production-legend" aria-label="Position colors">
          {legend.map((label) => <li key={label} style={{ '--position-color': positionStyles[label].color }}><span aria-hidden="true" />{label}</li>)}
        </ul>
        <ol className="production-chart" style={{ '--zero-position': `${zero}%` }} aria-label="Players ranked by starter points">
          {players.map((player) => {
            const position = positionFor(player);
            const share = total > 0 ? `${(player.points / total * 100).toFixed(1)}% of production` : null;
            return (
              <li className="production-row" key={player.key} style={{ '--position-color': position.color }}>
                <div className="production-player">
                  <img src={player.headshot_image} alt="" loading="lazy" onError={(event) => { event.currentTarget.style.visibility = 'hidden'; }} />
                  <div className="production-player-label">
                    <div className="production-name">{player.name}</div>
                    <div className="production-player-meta"><span className="production-position">{player.positions?.join('/') || position.label}</span><span>{player.starts} {player.starts === 1 ? 'start' : 'starts'}</span></div>
                  </div>
                </div>
                <div className="production-track" aria-hidden="true">
                  <span className="production-bar" style={{
                    left: `${player.points < 0 ? (player.points - minimum) / range * 100 : zero}%`,
                    width: `${Math.abs(player.points) / range * 100}%`,
                  }} />
                </div>
                <div className="production-value"><strong>{formatPoints(player.points)}<span className="visually-hidden"> points</span></strong>{share && <span>{share}</span>}</div>
              </li>
            );
          })}
        </ol>
        <p className="muted small-note">{formatPoints(total)} starter points · Bars share a common scale. FLEX starts use the player’s football position.</p>
      </> : <p className="empty-state">No regular-season starts yet.</p>}
    </section>
  );
}
