import React from 'react';
import { teamHref } from './dashboardData';

export default function DraftPicks({ team }) {
  const picks = team.draft_picks;
  const available = picks?.status === 'available';
  return <section className="panel" aria-labelledby="draft-picks-title">
    <div className="section-heading">
      <div><p className="eyebrow">Plan for the next draft</p><h2 id="draft-picks-title">{picks?.season ? `${picks.season} draft picks` : 'Draft picks'}</h2></div>
      {available && <span className="count-badge">{picks.owned.length} picks owned</span>}
    </div>
    {available ? <>
      <p className="muted small-note insights-description">Your picks by round, including completed trades. Overall pick numbers depend on next year’s draft order.</p>
      <div className="draft-picks-grid">{Array.from({ length: picks.rounds }, (_, index) => {
        const round = index + 1;
        const owned = picks.owned.filter((pick) => pick.round === round);
        const traded = picks.traded_away.find((pick) => pick.round === round);
        return <article className={`draft-round${traded || owned.some((pick) => String(pick.original_team.team_id) !== String(team.team_id)) ? ' draft-round-changed' : ''}`} key={round}>
          <div className="draft-round-heading"><h3>Round {round}</h3><span className="muted">{owned.length} {owned.length === 1 ? 'pick' : 'picks'}</span></div>
          {owned.length ? <ul>{owned.map((pick) => {
            const original = pick.original_team;
            const own = String(original.team_id) === String(team.team_id);
            return <li key={original.team_key ?? original.team_id}>{own ? 'Your own pick' : <><span className="acquired-pick">Acquired</span><span>Originally <a href={teamHref(original)}>{original.name}</a></span></>}</li>;
          })}</ul> : <p className="muted draft-no-picks">No picks owned</p>}
          {traded && <p className="draft-pick-away">Your pick → <a href={teamHref(traded.owner)}>{traded.owner.name}</a></p>}
        </article>;
      })}</div>
    </> : <p className="muted">Draft-pick ownership is unavailable right now.</p>}
  </section>;
}
